"""Resumos autorais curtos e referências oficiais para a grade ADS."""

CONTEUDOS = [
{"materia":"Banco de Dados","fonte":"PostgreSQL Global Development Group","url":"https://www.postgresql.org/docs/current/tutorial.html","resumo":"Bancos relacionais organizam dados em tabelas. Cada linha representa um registro e cada coluna um atributo. SQL permite definir estruturas (DDL), consultar e alterar dados (DML) e relacionar tabelas por chaves. Chaves primárias identificam registros; chaves estrangeiras preservam relações. Restrições e transações ajudam a manter consistência. Estude SELECT, filtros, JOIN, agregações e normalização antes de avançar para índices e desempenho.","pergunta":"Qual é a função principal de uma chave primária?","alternativas":["Identificar unicamente cada registro","Criptografar a tabela","Ordenar todos os resultados","Substituir consultas SQL"],"correta":1,"explicacao":"A chave primária distingue cada registro da tabela e não deve se repetir.","cards":[("O que é chave estrangeira?","Coluna que referencia uma chave de outra tabela e representa uma relação."),("Para que serve JOIN?","Combinar linhas relacionadas de duas ou mais tabelas numa consulta.")]},
{"materia":"Matemática Aplicada à Informática","fonte":"MIT OpenCourseWare","url":"https://ocw.mit.edu/courses/6-1200j-mathematics-for-computer-science-spring-2024/","resumo":"A matemática discreta fornece ferramentas para raciocinar sobre computação. Proposições e lógica formalizam condições; conjuntos e relações modelam coleções e vínculos; funções descrevem correspondências. Técnicas de prova, como indução, justificam propriedades de algoritmos. Combinatória conta possibilidades, enquanto probabilidade modela incerteza. Grafos representam redes e dependências. Ao estudar, traduza o problema para definições precisas, explicite hipóteses e verifique casos pequenos.","pergunta":"Qual técnica é especialmente adequada para provar propriedades definidas recursivamente?","alternativas":["Indução matemática","Ordenação por seleção","Criptografia simétrica","Normalização de tabelas"],"correta":1,"explicacao":"A indução verifica um caso base e demonstra que cada passo implica o seguinte.","cards":[("O que é uma proposição?","Uma afirmação declarativa que pode ser verdadeira ou falsa."),("Quais etapas básicas da indução?","Caso base e passo indutivo.")]},
{"materia":"Projeto Integrador: Introdução à Linguagem de Programação","fonte":"Harvard CS50","url":"https://cs50.harvard.edu/x/","resumo":"Programar é expressar uma solução em instruções que o computador executa. Comece decompondo o problema em entradas, processamento e saídas. Variáveis armazenam valores; expressões calculam; condicionais escolhem caminhos; laços repetem; funções organizam tarefas. Tipos ajudam a interpretar dados e evitar operações inválidas. Teste com casos comuns, limites e entradas inesperadas. Leia mensagens de erro e reduza o problema até encontrar a causa.","pergunta":"Qual estrutura permite repetir um bloco enquanto uma condição é satisfeita?","alternativas":["Laço de repetição","Declaração de tipo","Comentário","Importação"],"correta":1,"explicacao":"Laços, como while e for, executam um bloco repetidamente conforme uma condição ou sequência.","cards":[("O que é variável?","Nome associado a um valor usado e possivelmente atualizado pelo programa."),("Para que serve uma função?","Agrupar instruções reutilizáveis com uma responsabilidade definida.")]},
{"materia":"Sistemas Operacionais","fonte":"OSTEP — Remzi e Andrea Arpaci-Dusseau","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","resumo":"O sistema operacional gerencia recursos e oferece abstrações aos programas. Processos representam programas em execução; threads permitem concorrência dentro de um processo. O escalonador compartilha CPU, a memória virtual isola espaços de endereçamento e o sistema de arquivos organiza dados persistentes. Concorrência introduz disputas e condições de corrida, exigindo sincronização. Segurança e permissões controlam acesso. Analise como cada abstração simplifica o uso do hardware e quais custos ela traz.","pergunta":"Qual mecanismo dá a cada processo a impressão de possuir seu próprio espaço de memória?","alternativas":["Memória virtual","DNS","Chave primária","CSS"],"correta":1,"explicacao":"A memória virtual mapeia endereços do processo para a memória física e fornece isolamento.","cards":[("O que é processo?","Uma instância de programa em execução, com estado e recursos associados."),("O que é condição de corrida?","Resultado que depende da ordem imprevisível de acessos concorrentes a dados compartilhados.")]},
{"materia":"Tecnologias da Computação","fonte":"Harvard CS50","url":"https://cs50.harvard.edu/x/","resumo":"Um computador transforma dados por meio de componentes de hardware e software. A CPU executa instruções, a memória mantém dados em uso e o armazenamento preserva dados sem energia. Sistemas representam números e texto em bits; a escolha da representação afeta precisão e limites. Software de sistema gerencia recursos e aplicações resolvem tarefas do usuário. Compreender essas camadas facilita diagnosticar lentidão, incompatibilidade e falhas.","pergunta":"Qual componente executa instruções de programas?","alternativas":["CPU","Monitor","Roteador doméstico","Impressora"],"correta":1,"explicacao":"A CPU interpreta e executa instruções, coordenando operações do computador.","cards":[("Qual diferença entre RAM e armazenamento?","RAM é volátil e usada durante a execução; armazenamento mantém dados sem energia."),("Em que unidade se representa informação digital?","Bits, agrupados em unidades maiores como bytes.")]},
{"materia":"Comunicação Profissional","fonte":"Purdue OWL","url":"https://owl.purdue.edu/owl/subject_specific_writing/professional_technical_writing/","resumo":"Comunicação técnica eficaz começa pela audiência e pelo objetivo. Organize a mensagem com contexto, informação principal e ação esperada. Prefira linguagem direta, termos consistentes, frases claras e estrutura escaneável com títulos e listas. Em relatórios, separe fatos, análise e recomendações; em mensagens profissionais, indique assunto e prazo. Revise precisão, tom, acessibilidade e referências. Diagramas e exemplos podem reduzir ambiguidades quando complementam o texto.","pergunta":"O que deve orientar o nível de detalhe de uma comunicação profissional?","alternativas":["A audiência e o objetivo","O tamanho da fonte apenas","A preferência do autor sem contexto","A quantidade de páginas"],"correta":1,"explicacao":"A comunicação deve adequar conteúdo, linguagem e formato ao público e ao resultado esperado.","cards":[("O que é voz ativa?","Construção em que o sujeito realiza a ação, geralmente tornando a frase mais direta."),("O que verificar ao revisar um relatório?","Precisão, organização, clareza, tom e referências.")]},
{"materia":"Algoritmo e Estrutura de Dados","fonte":"OpenDSA — Virginia Tech","url":"https://opendsa.cs.vt.edu/","resumo":"Algoritmos definem passos finitos para resolver problemas; estruturas de dados organizam informações para operações eficientes. Vetores oferecem acesso por índice; listas facilitam inserções em certas posições; pilhas seguem LIFO e filas FIFO; árvores e tabelas hash apoiam buscas e relações. Complexidade de tempo e espaço descreve como o custo cresce com a entrada. Compare operações e escolha a estrutura conforme o padrão de uso, considerando também simplicidade e memória.","pergunta":"Qual estrutura segue a regra LIFO?","alternativas":["Pilha","Fila","Árvore de busca","Grafo"],"correta":1,"explicacao":"LIFO significa último a entrar, primeiro a sair; é o comportamento de uma pilha.","cards":[("O que expressa Big O?","Uma classificação assintótica do crescimento do custo de um algoritmo."),("O que significa FIFO?","Primeiro a entrar, primeiro a sair; regra típica de uma fila.")]},
{"materia":"Análise e Modelagem de Sistemas","fonte":"Object Management Group — UML","url":"https://www.omg.org/uml/","resumo":"Analisar sistemas é compreender necessidades, regras e restrições antes de decidir uma solução. Requisitos funcionais descrevem comportamentos; não funcionais tratam qualidades como segurança, desempenho e acessibilidade. Modelos UML comunicam perspectivas: casos de uso mostram interações, classes organizam conceitos e sequências descrevem mensagens ao longo do tempo. Valide modelos com usuários e cenários reais. Modelagem ajuda a revelar lacunas, mas deve permanecer proporcional ao problema.","pergunta":"Qual tipo de requisito descreve desempenho ou segurança?","alternativas":["Não funcional","Caso de uso","Chave primária","Algoritmo de ordenação"],"correta":1,"explicacao":"Requisitos não funcionais especificam atributos de qualidade e restrições do sistema.","cards":[("Para que serve um diagrama de casos de uso?","Representar atores e objetivos/interações com o sistema."),("O que é requisito funcional?","Comportamento ou serviço que o sistema deve oferecer.")]},
{"materia":"Programação Front-End","fonte":"MDN Web Docs","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development","resumo":"Front-end é a parte da aplicação com que a pessoa interage no navegador. HTML estrutura o conteúdo, CSS define apresentação e layouts, e JavaScript adiciona comportamento. Uma interface robusta usa semântica, navegação por teclado, contraste adequado e feedback claro. Separe estrutura, estilo e lógica para facilitar manutenção. Teste em diferentes tamanhos de tela e navegadores, e evite manipular dados do usuário sem validação no servidor.","pergunta":"Qual tecnologia define a estrutura semântica de uma página?","alternativas":["HTML","CSS","SQL","DNS"],"correta":1,"explicacao":"HTML descreve a estrutura e o significado do conteúdo da página.","cards":[("Para que serve CSS?","Controlar apresentação visual e layout de documentos web."),("O que significa HTML semântico?","Usar elementos que comunicam o significado e a estrutura do conteúdo.")]},
{"materia":"Projeto Integrador: Arquitetura de Computadores","fonte":"Nand2Tetris — Noam Nisan e Shimon Schocken","url":"https://www.nand2tetris.org/course","resumo":"Arquitetura de computadores conecta representação binária, lógica digital, processador, memória e instruções. Portas lógicas combinam bits para realizar operações; circuitos sequenciais armazenam estado. A CPU busca, decodifica e executa instruções, interagindo com memória e dispositivos. A arquitetura de conjunto de instruções define a interface visível ao software. Projetos didáticos que constroem camadas de baixo para cima mostram como abstrações simples formam sistemas complexos.","pergunta":"Qual ciclo básico descreve o trabalho da CPU?","alternativas":["Buscar, decodificar e executar","Compilar, publicar e indexar","Conectar, estilizar e renderizar","Criar, normalizar e consultar"],"correta":1,"explicacao":"A CPU busca uma instrução, decodifica seu significado e executa a operação.","cards":[("O que é bit?","Unidade básica de informação digital, com valor 0 ou 1."),("O que define uma ISA?","Instruções, registradores e comportamentos que formam a interface software-hardware.")]},
{"materia":"Debates Contemporâneos","fonte":"UNESCO — Recomendação sobre Ética da IA","url":"https://www.unesco.org/ethics-ai/en/recommendation","resumo":"Tecnologias digitais produzem benefícios e impactos sociais distribuídos de forma desigual. Avalie privacidade, vieses, acessibilidade, sustentabilidade, trabalho e responsabilidade. Sistemas de IA dependem de dados, objetivos e decisões humanas; resultados podem errar ou reproduzir desigualdades. Uma análise responsável identifica grupos afetados, riscos, formas de contestação e mecanismos de supervisão. Compare evidências e perspectivas, distinguindo fatos, opiniões e incertezas.","pergunta":"Uma avaliação ética de IA deve considerar quem pode ser afetado?","alternativas":["Sim, incluindo grupos vulneráveis e impactos","Não, apenas a precisão técnica","Somente quem desenvolveu o sistema","Apenas o custo de hardware"],"correta":1,"explicacao":"Avaliações éticas consideram impactos sobre pessoas, grupos e direitos, inclusive desigualdades.","cards":[("O que é viés algorítmico?","Padrão sistemático de resultados desiguais ou distorcidos associado a dados, objetivos ou decisões."),("Por que supervisão humana importa?","Permite questionar decisões, corrigir falhas e atribuir responsabilidade.")]},
{"materia":"Programação Orientada a Objeto","fonte":"dev.java — Oracle","url":"https://dev.java/learn/language/oop/","resumo":"Orientação a objetos organiza software em objetos que combinam estado e comportamento. Classes definem estruturas; objetos são instâncias. Encapsulamento protege invariantes e controla acesso. Herança permite especialização, mas pode criar acoplamento; composição frequentemente favorece flexibilidade. Polimorfismo permite tratar implementações diferentes por uma interface comum. Modele responsabilidades coesas e evite hierarquias profundas. Em Java, tipos, métodos e interfaces expressam contratos verificáveis pelo compilador.","pergunta":"O que é uma instância de uma classe?","alternativas":["Um objeto criado a partir da classe","Uma consulta SQL","Um arquivo CSS","Uma variável de ambiente"],"correta":1,"explicacao":"A classe descreve uma forma; a instância é um objeto concreto criado com base nela.","cards":[("O que é encapsulamento?","Restringir e organizar acesso ao estado interno por meio de uma interface controlada."),("O que é polimorfismo?","Usar uma interface comum para trabalhar com diferentes implementações.")]},
{"materia":"Projeto Integrador: Engenharia de Software","fonte":"The Open Source Software Engineering Book","url":"https://www.swebook.org/","resumo":"Engenharia de software aplica práticas sistemáticas ao ciclo de vida de sistemas: requisitos, desenho, implementação, testes, entrega e manutenção. Controle de versão registra mudanças e facilita colaboração. Integração frequente reduz conflitos; revisão de código compartilha conhecimento. Testes em níveis diferentes verificam unidades, integração e comportamento. Dívida técnica e mudanças de requisitos exigem priorização contínua. Documente decisões relevantes e mantenha cada incremento pequeno, observável e validável.","pergunta":"Qual prática ajuda a encontrar problemas em mudanças antes da integração?","alternativas":["Revisão de código","Renomear variáveis aleatoriamente","Remover testes","Adiar toda integração"],"correta":1,"explicacao":"A revisão permite que colegas examinem alterações, apontem riscos e compartilhem contexto.","cards":[("O que é controle de versão?","Registro rastreável de mudanças em arquivos ao longo do tempo."),("Qual objetivo de integração contínua?","Integrar e verificar mudanças frequentemente para detectar falhas cedo.")]},
{"materia":"Redes de Computadores e Segurança da Informação","fonte":"Cisco Networking Academy","url":"https://www.cisco.com/site/us/en/learn/training-certifications/training/netacad/index.html","resumo":"Redes conectam dispositivos para trocar dados por protocolos. IP endereça e encaminha pacotes; TCP oferece entrega ordenada e controle de fluxo; DNS traduz nomes em endereços. Segurança protege confidencialidade, integridade e disponibilidade. Reduza riscos com atualizações, autenticação forte, privilégios mínimos, cópias de segurança e criptografia em trânsito. Identifique ameaças, ativos e controles; nenhuma medida isolada elimina todos os riscos.","pergunta":"Qual serviço traduz nomes de domínio em endereços IP?","alternativas":["DNS","CSS","SQL","RAM"],"correta":1,"explicacao":"O DNS resolve nomes legíveis, como domínios, para endereços usados na rede.","cards":[("Quais são os três objetivos clássicos da segurança?","Confidencialidade, integridade e disponibilidade."),("Para que serve TCP?","Fornecer comunicação confiável e ordenada entre aplicações.")]},
{"materia":"Tecnologias da Web","fonte":"MDN Web Docs","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development","resumo":"A Web combina clientes, servidores, protocolos e padrões. O navegador envia requisições HTTP; o servidor responde com recursos como HTML, CSS, JavaScript ou JSON. URLs identificam recursos e métodos HTTP expressam operações. Cookies e armazenamento local mantêm estado com implicações de privacidade. APIs conectam aplicações e precisam de contratos, autenticação e tratamento de erros. HTTPS protege a comunicação com TLS, mas não substitui validações nem controles de acesso.","pergunta":"Qual protocolo é usado na comunicação entre navegador e servidor web?","alternativas":["HTTP","SMTP apenas","HDMI","USB"],"correta":1,"explicacao":"HTTP define requisições e respostas para transferir recursos da Web; HTTPS adiciona proteção TLS.","cards":[("O que é API web?","Interface acessível pela rede que permite a sistemas trocar dados e solicitar operações."),("O que HTTPS acrescenta ao HTTP?","Proteção da comunicação com TLS, incluindo criptografia e autenticação do servidor.")]},
{"materia":"Desenvolvimento de Jogos","fonte":"Godot Engine Documentation","url":"https://docs.godotengine.org/en/latest/getting_started/first_2d_game/index.html","resumo":"Um jogo combina regras, entrada, estado, feedback e apresentação. Loops atualizam a simulação em passos; entidades e componentes organizam comportamentos. Física, colisões, animações, áudio e interface precisam responder às ações do jogador. Protótipos pequenos ajudam a validar a mecânica central antes de produzir conteúdo. Teste controles, dificuldade, desempenho e acessibilidade. Em motores como Godot, cenas e nós permitem compor objetos reutilizáveis.","pergunta":"Qual é uma boa primeira etapa para validar a diversão de uma ideia de jogo?","alternativas":["Criar um protótipo simples da mecânica central","Produzir todos os níveis finais","Escrever apenas a documentação","Otimizar sem medir"],"correta":1,"explicacao":"Um protótipo testa rapidamente a mecânica e reduz o custo de rever a ideia.","cards":[("O que é loop de jogo?","Ciclo que processa entradas, atualiza o estado e apresenta o resultado repetidamente."),("O que é prototipagem?","Construir uma versão simples para testar hipóteses de design.")]},
{"materia":"Desenvolvimento e Sustentabilidade","fonte":"Nações Unidas — Objetivos de Desenvolvimento Sustentável","url":"https://www.un.org/sustainabledevelopment/sustainable-development-goals/","resumo":"Sustentabilidade considera dimensões ambientais, sociais e econômicas ao longo do tempo. Tecnologia pode ampliar acesso e eficiência, mas também consumir energia, recursos e gerar resíduos eletrônicos. Avalie ciclo de vida, acessibilidade, inclusão, privacidade e impactos indiretos. Indicadores ajudam a comparar alternativas, desde que contexto e limites sejam claros. Decisões responsáveis buscam reduzir danos e distribuir benefícios, alinhando projetos a necessidades reais e objetivos sustentáveis.","pergunta":"Uma análise de sustentabilidade deve considerar somente o impacto ambiental?","alternativas":["Não; também dimensões sociais e econômicas","Sim, sempre","Somente o preço inicial","Somente a velocidade da aplicação"],"correta":1,"explicacao":"Sustentabilidade integra dimensões ambientais, sociais e econômicas.","cards":[("O que é ciclo de vida de um produto?","Etapas desde extração e fabricação até uso, manutenção e descarte."),("Por que avaliar acessibilidade?","Para que pessoas com diferentes capacidades possam usar o produto com autonomia.")]},
{"materia":"Gerenciamento de Projetos","fonte":"Scrum Guides — Schwaber e Sutherland","url":"https://scrumguides.org/download.html","resumo":"Gerenciar projetos é coordenar objetivos, escopo, prazo, recursos, riscos e comunicação. Abordagens preditivas planejam etapas com antecedência; abordagens adaptativas entregam incrementos e aprendem com feedback. No Scrum, Product Owner ordena o Product Backlog, Developers criam o incremento e Scrum Master apoia a efetividade. Eventos ajudam inspecionar e adaptar. Escolha práticas segundo incerteza e contexto, mantendo transparência sobre progresso e riscos.","pergunta":"No Scrum, quem ordena o Product Backlog para maximizar valor?","alternativas":["Product Owner","Scrum Master sozinho","Cliente sem colaboração","Equipe de infraestrutura"],"correta":1,"explicacao":"O Product Owner é responsável pela gestão efetiva do Product Backlog, incluindo sua ordenação.","cards":[("O que é incremento no Scrum?","Resultado utilizável que atende à Definition of Done ao fim de um Sprint."),("Qual propósito da retrospectiva?","Inspecionar como o trabalho ocorreu e planejar melhorias para o próximo ciclo.")]},
{"materia":"Programação Back-End","fonte":"Flask Documentation","url":"https://flask.palletsprojects.com/en/stable/tutorial/","resumo":"Back-end implementa regras, integrações e persistência no servidor. Rotas recebem requisições, validam entradas, autorizam ações e retornam respostas. Separe responsabilidades entre apresentação, serviços e dados. Use consultas parametrizadas, hashing de senhas, gerenciamento de sessões e proteção CSRF. Trate erros sem expor detalhes internos. Logs ajudam diagnóstico, mas não devem registrar segredos. Em Flask, aplicações pequenas podem crescer com blueprints e configuração por ambiente.","pergunta":"Como evitar que valores de entrada sejam interpretados como parte do SQL?","alternativas":["Usar consultas parametrizadas","Concatenar strings","Desativar validações","Exibir erros internos"],"correta":1,"explicacao":"Parâmetros mantêm dados separados do comando SQL e reduzem risco de injeção.","cards":[("O que é rota?","Regra que associa um caminho/método HTTP a uma operação da aplicação."),("Por que armazenar senha com hash?","Para não persistir a senha em texto claro; use algoritmo próprio para senhas e sal adequado.")]},
{"materia":"Projeto Integrador: Computação em Nuvem","fonte":"Amazon Web Services — Cloud Practitioner","url":"https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/clf-technologies-concepts.html","resumo":"Computação em nuvem oferece recursos sob demanda pela rede. Modelos de serviço incluem infraestrutura, plataforma e software como serviço; modelos de implantação variam entre nuvem pública, privada e híbrida. Elasticidade ajusta capacidade; alta disponibilidade distribui falhas, mas exige arquitetura e custo. O provedor e o cliente compartilham responsabilidades de segurança. Planeje identidade, backups, monitoramento, regiões e orçamento antes da migração.","pergunta":"O que caracteriza elasticidade na nuvem?","alternativas":["Ajustar recursos conforme a demanda","Comprar hardware fixo para sempre","Desativar monitoramento","Armazenar senhas em código"],"correta":1,"explicacao":"Elasticidade permite aumentar ou reduzir recursos conforme a necessidade de carga.","cards":[("O que é modelo IaaS?","Oferta de recursos de infraestrutura virtualizados, como computação, rede e armazenamento."),("O que significa responsabilidade compartilhada?","Segurança é dividida entre provedor e cliente conforme o serviço utilizado.")]},
{"materia":"Empreendedorismo","fonte":"Sebrae — Aprender a empreender","url":"https://sebrae.com.br/sites/PortalSebrae/cursosonline/aprender-a-empreender,b070b8a6a28bb610VgnVCM1000004c00210aRCRD","resumo":"Empreender começa por entender uma necessidade e testar se uma proposta cria valor para um público. Converse com clientes, observe alternativas existentes e formule hipóteses sobre problema, solução, preço e canais. Um protótipo ou experimento simples reduz incerteza antes de grandes investimentos. Avalie custos, receitas, fluxo de caixa e riscos. Diferencie interesse declarado de comportamento observado e aprenda com resultados para ajustar o modelo.","pergunta":"Qual é o objetivo de validar uma hipótese de negócio com clientes?","alternativas":["Reduzir incertezas antes de investir mais","Garantir sucesso sem riscos","Evitar ouvir usuários","Substituir planejamento financeiro"],"correta":1,"explicacao":"Testes com clientes fornecem evidências para ajustar a proposta e reduzir riscos.","cards":[("O que é proposta de valor?","Benefício relevante que uma solução oferece a um público para atender uma necessidade."),("Por que acompanhar fluxo de caixa?","Para entender entradas, saídas e capacidade de cumprir obrigações ao longo do tempo.")]},
{"materia":"Projeto Integrador: Desenvolvimento de Aplicativos Móveis","fonte":"Android Developers","url":"https://developer.android.com/courses","resumo":"Aplicativos móveis devem considerar telas variadas, conectividade instável, consumo de bateria e permissões. Projetar para tarefas prioritárias melhora a experiência; navegação clara e acessibilidade reduzem barreiras. Persista dados necessários, proteja informações pessoais e solicite permissões no contexto de uso. Teste em emuladores e dispositivos reais, com diferentes tamanhos e versões. Planeje estados sem conexão, falhas e atualizações do aplicativo.","pergunta":"Quando solicitar uma permissão sensível ao usuário?","alternativas":["No contexto em que o recurso é necessário, explicando o motivo","Todas no primeiro instante, sem explicação","Nunca, mesmo se necessária","Somente depois de coletar os dados"],"correta":1,"explicacao":"Contexto e transparência ajudam a pessoa a entender a necessidade e decidir conscientemente.","cards":[("Por que testar em dispositivos reais?","Para observar diferenças de hardware, desempenho, sensores e comportamento de fabricantes."),("O que significa design responsivo móvel?","Adaptar layout e interação a tamanhos e condições variadas de tela.")]},
{"materia":"Teste e Qualidade de Software","fonte":"pytest Documentation","url":"https://pytest.org/en/stable/getting-started.html","resumo":"Qualidade é construída por prevenção, verificação e feedback. Testes unitários verificam partes pequenas; testes de integração avaliam componentes conectados; testes de sistema observam fluxos completos. Bons casos cobrem comportamento esperado, limites e falhas. Testes automatizados devem ser repetíveis, independentes e claros. Em pytest, funções com prefixo test e assert expressam verificações simples. Uma suíte rápida e confiável incentiva execução frequente, sem substituir revisão e observação em produção.","pergunta":"O que caracteriza um teste unitário?","alternativas":["Verificar uma unidade pequena de comportamento isoladamente","Testar toda a produção manualmente","Medir apenas o tamanho do código","Substituir todos os testes de integração"],"correta":1,"explicacao":"Testes unitários focam unidades pequenas para localizar falhas com precisão.","cards":[("O que é teste de regressão?","Verificação de que mudanças não quebraram comportamentos que já funcionavam."),("Como pytest identifica testes comuns?","Por nomes de arquivo e funções que seguem os padrões test_*.py e test_*.")]},
]

